Contract ProcessSaleService::enterItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          currentSale:Sale = CurrentSale, item:Item = Item.allInstance()->any(o | o.Barcode = barcode), stockNum:Integer = item.StockNumber, saleLine:SalesLineItem = SalesLineItem {}

            precondition:
          currentSale.oclIsUndefined() = false and currentSale.IsComplete = false and item.oclIsUndefined() = false and stockNum > 0

            postcondition:
          let saleLine:SalesLineItem in saleLine.oclIsNew() and CurrentSale.ContainedSalesLine->includes(saleLine) and saleLine.BelongedSale = CurrentSale and saleLine.Quantity = quantity and item.StockNumber = stockNum - quantity and saleLine.Subamount = item.Price * quantity and saleLine.save() and result = true

        }
